declare(strict_types=1);use Vendi\Database\Connection;use Vendi\Http\ApiGuard;require dirname(__DIR__,3).'/vendor/autoload.php';session_start();header('Content-Type: application/json; charset=utf-8');try{$u=ApiGuard::session();$db=Connection::get();ApiGuard::permission($db,$u,'integrations.manage');$b=(int)$u['business_id'];if($_SERVER['REQUEST_METHOD']==='GET'){$q=$db->prepare("SELECT provider,branch_id,config_json,active FROM integration_credentials WHERE business_id=?");$q->execute([$b]);$rows=[];foreach($q->fetchAll()as$r){$c=json_decode((string)$r['config_json'],true)?:[];foreach(['access_token','client_secret']as$k)if(!empty($c[$k]))$c[$k]='••••••••';$r['config']=$c;unset($r['config_json']);$rows[]=$r;}echo json_encode(['ok'=>true,'integrations'=>$rows],JSON_UNESCAPED_UNICODE);exit;}ApiGuard::csrf();$x=json_decode(file_get_contents('php://input'),true)?:[];$provider=(string)($x['provider']??'');if(!in_array($provider,['whatsapp','skydropx'],true))throw new RuntimeException('Proveedor inválido.');$config=(array)($x['config']??[]);$existing=$db->prepare("SELECT config_json FROM integration_credentials WHERE business_id=? AND branch_id IS NULL AND provider=?");$existing->execute([$b,$provider]);$old=json_decode((string)$existing->fetchColumn(),true)?:[];foreach(['access_token','client_secret']as$k)if(($config[$k]??'')==='••••••••')$config[$k]=$old[$k]??'';$q=$db->prepare("INSERT INTO integration_credentials(business_id,branch_id,provider,config_json,active) VALUES(?,NULL,?,?,1) ON DUPLICATE KEY UPDATE config_json=VALUES(config_json),active=1");$q->execute([$b,$provider,json_encode($config,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)]);echo json_encode(['ok'=>true]);}catch(Throwable$e){http_response_code(400);echo json_encode(['ok'=>false,'error'=>$e->getMessage()],JSON_UNESCAPED_UNICODE);}
